package in.campustwin.explanation;

import java.util.List;

/**
 * Structured explanation prose generated by LLM or deterministic template.
 * The model owns ONLY these prose fields; all authoritative metrics,
 * safety checks, and eligibility rules remain backend-owned.
 */
public record GeneratedExplanation(
    String summary,
    String reason,
    List<String> assumptions,
    List<String> suggestedChecks
) {}
